custom_defined_behaviors:
behaviors {
    td_caps: td_caps {
        compatible = "zmk,behavior-tap-dance";
        label = "TD_CAPS";
        #binding-cells = <0>;
        tapping-term-ms = <250>;
        bindings = <&caps_word>, <&kp CAPS>;
    };
    td_mouse: td_mouse {
        compatible = "zmk,behavior-tap-dance";
        label = "TD_MOUSE";
        #binding-cells = <0>;
        tapping-term-ms = <200>;
        bindings = <&kp LG(SPACE)>, <&tog 8>;
    };
    td_copy_paste: td_copy_paste {
        compatible = "zmk,behavior-tap-dance";
        label = "TD_COPY_PASTE";
        #binding-cells = <0>;
        tapping-term-ms = <200>;
        bindings = <&kp LG(C)>, <&kp LG(V)>;
    };
    td_copy_paste_pc: td_copy_paste_pc {
        compatible = "zmk,behavior-tap-dance";
        label = "TD_COPY_PASTE_PC";
        #binding-cells = <0>;
        tapping-term-ms = <200>;
        bindings = <&kp LC(C)>, <&kp LC(V)>;
    };
};
